	" }\n  if (!entries.length) { return; }\n\n  var files = [];\n  var anyFolder = entries.some(function (en"
	"try) { return entry.isDirectory; });\n  var chain = Promise.resolve();\n\n  entries.forEach(function (e"
	"ntry) {\n    chain = chain.then(function () { return walkEntry(entry, \"\", files); });\n  });\n\n  chain."
	"then(function () {\n    if (files.length) { enqueue(files, anyFolder); }\n  });\n});\n\n/* --- go -------"
	"---------------------------------------------------------- */\n\nfetch(\"hostname\", { cache: \"no-store\""
	" })\n  .then(function (res) { return res.ok \? res.text() : \"\"; })\n  .then(function (name) {\n    devic"
	"eName = (name || \"\").trim().toUpperCase();\n    if (deviceName) { draw(); } // the title and the firs"
	"t crumb are its name\n  })\n  .catch(function () { /* the name is decoration; the page works without i"
	"t */ });\n\nupdateHiddenButton();\nload(CARD);\n</script>\n</body>\n</html>\n";

#endif /* WEBPAGE_H */
